function U.now()
return os.clock()
end
function U.json(vb)
local wb,xb=pcall(J.JSONEncode,J,vb)
return wb and xb or Sme[2018]
end
function U.unjson(yb)
local zb,Ab=pcall(J.JSONDecode,J,yb)
return zb and Ab or nil
end
function U.readJson(Bb)
local Cb,Db=pcall(function()
return isfile(Bb)and readfile(Bb)or nil
end)
return Cb and Db and U.unjson(Db)or nil
end
function U.writeJson(Eb,Fb)
pcall(function()
if not isfolder(N.FOLDER)then
makefolder(N.FOLDER)
end
end)
pcall(writefile,Eb,U.json(Fb))
end
function U.fmt(Gb)
Gb=tonumber(Gb)or 0
if Gb>=1e6 then
return string.format(Sme[2019],Gb/1e6)
end
if Gb>=1e4 then
return string.format(Sme[2020],Gb/1e3)
end
return tostring(math.floor(Gb+0.5))
end
function U.clamp(Hb,Ib,Jb)
return math.max(Ib,math.min(Jb,Hb))
end
function U.count(Kb)
local Lb=0
for Mb in pairs(Kb or{})do
Lb=Lb+1
end
return Lb
end
function U.list(Nb)
if type(Nb)~=Sme[2021]then
return{}
end
if#Nb>0 then
return Nb
end
local Ob={}
for Pb in pairs(Nb)do
table.insert(Ob,Pb)
end
table.sort(Ob,function(Qb,Rb)
return(tonumber(Qb)or 0)<(tonumber(Rb)or 0)
end)
local Sb={}
for Tb,Ub in ipairs(Ob)do
table.insert(Sb,Nb[Ub])
end
return Sb
end
function U.flat(Vb)
return Vector3 .new(Vb.X,0,Vb.Z)
end
function U.plain(Wb,Xb)
local Yb=type(Wb)
if Yb==Sme[2022]or Yb==Sme[928]or Yb==Sme[2023]then
return Wb
end
if Yb~=Sme[2021]or(Xb or 0)>6 then
return nil
end
local Zb={}
for _b,cc in pairs(Wb)do
if type(_b)==Sme[2022]or type(_b)==Sme[928]then
Zb[_b]=U.plain(cc,(Xb or 0)+1)
end
end
return Zb
end
function F.log(dc,ec,fc)
if dc>(O.logLevel or 1)then
return
end
local gc=string.format(Sme[2024],os.date(Sme[2025]),ec,tostring(fc))
table.insert(R.lines,gc)
if#R.lines>250 then
table.remove(R.lines,1)
end
table.insert(R.pending,gc)
local hc=tostring(fc):lower()
if hc:find(Sme[2026])or hc:find(Sme[2027])or hc:find(Sme[2028])or ec==Sme[2029]then
R.problems=R.problems or{}
table.insert(R.problems,gc)
if#R.problems>30 then
table.remove(R.problems,1)
end
end
if O.logConsole then
print(Sme[2030]..gc)
end
end
function F.status(jc,kc)
Q[jc]=kc
F.statusAt=F.statusAt or{}
F.statusAt[jc]=os.time()
end
function F.flush()
if#R.pending==0 then
return
end
local lc=table.concat(R.pending,Sme[2031])..Sme[2031]
table.clear(R.pending)
pcall(function()
if not isfolder(N.FOLDER)then
makefolder(N.FOLDER)
end
if appendfile and isfile(N.LOGFILE)then
appendfile(N.LOGFILE,lc)
else
writefile(N.LOGFILE,lc)
end
end)
end
task.spawn(function()
while F.alive do
task.wait(3)
F.flush()
end
end)
do
local mc=U.readJson(N.SETTINGS)or{}
if mc.shareChosen~=true then
mc.shareStats=nil
end
if mc.autoTeamChosen~=true then
mc.autoTeam=nil
end
if mc.mmGuardChosen~=true then
mc.mmGuard=nil
end
for nc,oc in pairs(N.DEFAULTS)do
if mc[nc]~=nil and type(mc[nc])==type(oc)then
O[nc]=mc[nc]
else
O[nc]=oc
end
end
O.seenVersion=type(mc.seenVersion)==Sme[928]and mc.seenVersion or nil
if mc.griffinWatch==true and mc.snipeUnit==nil then
O.snipeOn,O.snipeUnit=true,Sme[1103]
end
if O.pickPortal==Sme[948]then
O.portals,O.pickPortal=false,Sme[943]
end
if O.huntCards==Sme[2032]then
O.huntCards=Sme[2033]
end
O.cfgv=1
if not O.simpleGui then
O.simpleGui=true
if not O.play then
O.master=false
