if not Rr[Vr]then
local Xr={}
for Yr,Zr in pairs(type(Sr[Vr])==Sme[2021]and Sr[Vr]or{})do
Xr[Yr]=Zr
end
for as,bs in pairs(type(Wr.nums)==Sme[2021]and Wr.nums or{})do
