end
local cs=Wr.trigger~=nil and tostring(Wr.trigger):find(Sme[2425],1,true)~=nil
if Wr.family==Sme[2204]then
local ds=(cs and pb.ABILITY_UPTIME or 1)*(Wr.who==Sme[2273]and pb.RANGE_SHARE or 1)
