function mb.weatherStrength(FD)
local GD=mb.fx(FD)
local HD=GD.dmg/GD.cd/GD.hp/GD.speed*(1+(GD.range-1)/2)
for JD,KD in pairs(GD.kinds)do
HD=HD*(1+bb.rogueShare(JD)*KD)
end
if GD.ice>0 then
local LD=bb.rogueShare(Sme[2154])
HD=HD*(LD+(1-LD)/(1-GD.ice+GD.ice/gb.modFactor(Sme[2560])))
end
if GD.fly>0 then
HD=HD*(1-GD.fly*0.5)
end
if GD.noCC then
HD=HD*0.95
end
if GD.shroud then
HD=HD*0.9
end
if GD.zap then
HD=HD*0.85
end
return HD/mb.weatherK(FD)
end
mb.WEATHER_K_MIN,mb.WEATHER_K_MAX,mb.WEATHER_K_RUNS=0.5,4,10
function mb.weatherK(MD)
local ND=MD and type(P.hunt)==Sme[2021]and type(P.hunt.wk)==Sme[2021]and P.hunt.wk[tostring(MD)]or nil
return type(ND)==Sme[2021]and tonumber(ND.k)or 1
