function mb.weatherLearn()
if bb.withOthers or#game:GetService(Sme[921]):GetPlayers()>1 then
return
end
local OD=bb.huntWeather or mb.weatherNow()
local PD,QD=bb.pred,bb.calRun
if not OD or type(PD)~=Sme[2021]or type(QD)~=Sme[2021]then
return
end
local function RD(SD,TD)
return type(SD)==Sme[2021]and tonumber(SD[TD]or SD[tostring(TD)])or nil
end
local UD={}
for VD=2,bb.wave()do
local WD,XD=RD(QD.alive,VD),RD(PD.aliveAt,VD)
