local ZD=P.hunt.wk[tostring(OD)]
local _D=math.min(mb.WEATHER_K_RUNS-1,type(ZD)==Sme[2021]and tonumber(ZD.n)or 0)
local aE=mb.weatherK(OD)
local bE=math.max(1,_D)
local cE=math.exp((bE*math.log(aE)+math.log(aE*YD))/(bE+1))
cE=U.clamp(cE,mb.WEATHER_K_MIN,mb.WEATHER_K_MAX)
bb.wkWas={w=tostring(OD),old=ZD}
P.hunt.wk[tostring(OD)]={k=cE,n=(type(ZD)==Sme[2021]and tonumber(ZD.n)or 0)+1,at=os.time()}
F.log(1,Sme[2561],string.format(Sme[2562],tostring(OD),YD,tostring(OD),cE,aE,P.hunt.wk[tostring(OD)].n))
end
function mb.cardGems(dE,eE)
