if ogb==Sme[2094]or cgb>=3 then
break
end
cgb=cgb+1
task.wait(3.5)
continue
end
while U.now()-mgb<5 and(tonumber((Wfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Xfb).xp)or 0)<=lgb do
task.wait(0.1)
end
local pgb=tonumber((Wfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Xfb).xp)or 0
if pgb>lgb then
bgb=bgb+1
for qgb,rgb in ipairs(jgb)do
dgb[rgb]=true
end
cb.add(string.format(Sme[3158],#jgb,Yfb),#jgb,Sme[3159],string.format(Sme[3160],U.fmt(pgb-lgb)))
F.log(1,Sme[2525],string.format(Sme[3161],#jgb,Yfb,U.fmt(pgb-lgb),kb.level(Wfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Xfb)))
elseif#jgb>20 then
ab.fuseBatch=20
F.log(1,Sme[2525],string.format(Sme[3162],#jgb,tostring(F.gameSaid(mgb)or(ngb and ogb)or Sme[2555])))
else
local sgb=F.gameSaid(mgb)
ab.pickNote.autoFuseXp=Sme[3163]..tostring(sgb or(ngb and ogb)or Sme[2555])..Sme[3164]
F.log(1,Sme[2525],Sme[3165]..tostring(sgb or(ngb and ogb)or Sme[2555]))
F.backoff(Sme[3156],1800)
break
end
end
end
