fjb.ok=true
end
end
fjb.pending=nil
F.log(1,Sme[3234],string.format(Sme[3235],Wib.label,V.name(Xib.id),fjb.out and(Sme[3236]..V.name(fjb.out))or Sme[942],fjb.ok and string.format(Sme[3237],math.floor((ib.perRun(Wib.key,Xib.id)or 0)+0.5),Xib.what,fjb.minutes,fjb.ownMin)or tostring(fjb.why)))
