if yrb and not yrb.legend_stage and not yrb.raid_world then
local zrb=U.list(yrb.levels)
local Arb=zrb[#zrb]
if Arb and not W.done(srb,Arb.id,Sme[947])then
trb,urb,vrb=xrb,zrb[1],Arb
break
end
end
end
if not(trb and rrb[trb]and urb and vrb)then
