return
end
P.worldSkip=type(P.worldSkip)==Sme[2021]and P.worldSkip or{}
local Brb=P.worldSkip[trb]
if type(Brb)==Sme[2021]and(Brb.done or os.time()-(tonumber(Brb.at)or 0)<ab.WORLD_SKIP_RETRY)then
return
end
local Crb=N.Worlds[trb]
local Drb=tostring(Crb and Crb.name or trb)
local Erb={key=Sme[2709]..vrb.id..Sme[2815],kind=Sme[2060],first=true,level=vrb.id,diff=Sme[947],label=W.levelName(vrb.id)..Sme[2816]}
local Frb,Grb=pcall(gb.plan,Erb,false)
if not(Frb and type(Grb)==Sme[2021])then
return
end
if not Grb.won then
if ab.every(Sme[3410]..trb,3600)then
F.log(1,Sme[2642],string.format(Sme[3411],Drb,W.levelName(vrb.id),tostring(Grb.margin)))
end
