task.wait(1)
if W.open(vrb.id)then
Nrb=true
break
end
end
local Orb=F.gameSaid(Krb)
P.worldSkip[trb]={at=os.time(),done=Nrb or nil,last=vrb.id,said=Orb and tostring(Orb):sub(1,80)or nil}
F.saveSoon()
if Nrb then
local Prb=(N.prof()or{}).level_data or{}
local Qrb={}
for Rrb,Srb in ipairs(U.list(Crb.levels))do
if Srb.id~=vrb.id and not Hrb[Srb.id]and W.done(Prb,Srb.id,Sme[947])then
table.insert(Qrb,W.levelName(Srb.id))
end
end
F.log(1,Sme[2642],string.format(Sme[3415],Drb,#Qrb>0 and(Sme[3416]..table.concat(Qrb,Sme[2133]))or Sme[3417],Orb and(Sme[3418]..tostring(Orb))or Sme[942]))
