function ab.relicClash(gvb)
local hvb=N.session()
local ivb={}
for jvb,kvb in ipairs(P.savedTeam or{})do
ivb[kvb]=true
end
local lvb={}
for mvb,nvb in ipairs(gvb)do
local ovb=hvb.collection:get_unit_by_uuid(nvb)
local pvb=ovb and ovb._equipped_relic and hvb.inventory:get_item_by_uuid(ovb._equipped_relic)
if pvb and pvb.item_id and(N.Items[pvb.item_id]or{}).unique_equip then
table.insert(lvb,{uuid=nvb,u=ovb,kind=pvb.item_id,relic=ovb._equipped_relic,k=(ivb[nvb]and 1e12 or 0)+kb.score(ovb)})
end
end
table.sort(lvb,function(qvb,rvb)
if qvb.k~=rvb.k then
return qvb.k>rvb.k
end
return qvb.uuid<rvb.uuid
end)
local svb={}
