P.relicOff[uvb.uuid]=uvb.relic
F.log(1,Sme[3069],string.format(Sme[3528],V.name(uvb.u.unit_id),vvb,V.name(svb[uvb.kind])))
else
F.log(1,Sme[3069],string.format(Sme[3529],V.name(uvb.u.unit_id),vvb,tostring(xvb)))
