end
end
W._sigAt=nil
if Yvb then
F.log(1,Sme[3069],Sme[3536].. #Lvb..Sme[3537]..tostring(Mvb))
else
local pwb={}
for qwb,rwb in ipairs(V.equipped())do
table.insert(pwb,V.name(rwb.id))
end
F.log(1,Sme[3069],Sme[3538]..tostring(Mvb)..Sme[3539]..table.concat(pwb,Sme[2133])..Sme[3540]..table.concat(Zvb,Sme[2396]))
