ab.LAB={EVERY=3,KINDS={story=true,raid=true,infinite=true},MIN_EVIDENCE=5,AGAIN=3600}
function ab.unitEvidence(_wb)
local axb=P.learn[_wb]
local bxb=axb and tonumber(axb.n)or 0
