local dxb=cxb and type(cxb.units)==Sme[2021]and cxb.units[_wb]
if type(dxb)==Sme[2021]then
bxb=bxb+(tonumber(dxb.matches)or 0)+(tonumber(dxb.matches3)or 0)
end
return bxb
end
function ab.unitLabSafe(exb)
if O.unitLab==false or type(exb)~=Sme[2021]or not ab.LAB.KINDS[exb.kind]or exb.first then
return false
end
if P.trial or(P.study and not P.study.done)or(type(P.testTeam)==Sme[2021]and(tonumber(P.testTeam.left)or 0)>0)or(P.train and P.train.on)or ab.partyRole()~=Sme[948]then
return false
end
local fxb,gxb=pcall(ab.matchOn,exb)
if fxb and gxb then
return false
end
local hxb=type(P.unitLab)==Sme[2021]and P.unitLab or{}
if hxb.pauseKey==exb.key and os.time()<(tonumber(hxb.pauseUntil)or 0)then
return false
end
local ixb=W.rec(exb.key)
local jxb,kxb=tonumber(ixb.runs)or 0,tonumber(ixb.wins)or 0
if exb.kind==Sme[2040]then
local lxb,mxb=pcall(W.infDaily,N.prof(),exb.level,W.infReach(exb.key))
return jxb>=3 and lxb and(tonumber(mxb)or 1)<=0
end
return jxb>=5 and(tonumber(ixb.streak)or 0)==0 and kxb/jxb>=0.9
end
function ab.unitLab(nxb)
if not ab.unitLabSafe(nxb)then
return
end
P.unitLab=type(P.unitLab)==Sme[2021]and P.unitLab or{}
local oxb=P.unitLab
oxb.tried=type(oxb.tried)==Sme[2021]and oxb.tried or{}
oxb.seen=(tonumber(oxb.seen)or 0)+1
if oxb.seen%ab.LAB.EVERY~=0 then
return
end
local pxb=N.session()
local qxb=V.equipped()
if not pxb or#qxb<2 then
return
end
local rxb={}
for sxb,txb in ipairs(qxb)do
rxb[txb.uuid]=true
rxb[txb.id]=true
end
local uxb,vxb,wxb
for xxb,yxb in pairs(pxb.profile_data.collection.owned_units)do
local zxb=yxb.unit_id
if not rxb[xxb]and not rxb[zxb]and N.Units[zxb]and not V.isFarm(zxb)and not V.allyBuff(zxb)and os.time()-(tonumber(oxb.tried[zxb])or 0)>ab.LAB.AGAIN then
local Axb=ab.unitEvidence(zxb)
if Axb<ab.LAB.MIN_EVIDENCE then
local Bxb=pxb.collection:get_unit_by_uuid(xxb)or yxb
local Cxb=kb.score(Bxb)
if Cxb>0 and(not uxb or Axb<vxb or(Axb==vxb and Cxb>wxb))then
uxb,vxb,wxb={uuid=xxb,id=zxb,u=Bxb},Axb,Cxb
end
end
end
end
if not uxb then
return
end
local Dxb,Exb
for Fxb,Gxb in ipairs(qxb)do
if not V.isFarm(Gxb.id)and not V.allyBuff(Gxb.id)and Gxb.uuid~=O.evolveUnit then
local Hxb=kb.score(Gxb.u)
if not Dxb or Hxb<Exb then
Dxb,Exb=Gxb,Hxb
end
end
end
if not Dxb then
return
end
oxb.tried[uxb.id]=os.time()
local Ixb=0
for Jxb in pairs(oxb.tried)do
Ixb=Ixb+1
if Ixb>300 then
oxb.tried[Jxb]=nil
end
end
local Kxb,Lxb=gb.levelFor(nxb)
if not Kxb then
return
end
local Mxb=gb.info(Kxb,nxb.key,Lxb,nxb.mod or W.ldMod(Kxb)or W.levelMod(nxb.level))
local Nxb={}
for Oxb,Pxb in ipairs(qxb)do
table.insert(Nxb,Pxb.uuid==Dxb.uuid and uxb.u or Pxb.u)
end
local Qxb,Rxb=pcall(gb.run,Mxb,gb.teamFrom(Nxb,Mxb.map),{hpMul=1.1})
local Sxb=Qxb and type(Rxb)==Sme[2021]and(Rxb.won or(Mxb.infinite and(tonumber(Rxb.wave)or 0)>=0.8*W.infReach(nxb.key)))
if not Sxb then
F.log(2,Sme[3551],string.format(Sme[3552],V.name(uxb.id),nxb.label))
return
end
local Txb={}
for Uxb,Vxb in ipairs(qxb)do
table.insert(Txb,Vxb.uuid==Dxb.uuid and uxb.uuid or Vxb.uuid)
end
if ab.equipTeam(Txb,Sme[3553]..V.name(uxb.id))then
oxb.now={id=uxb.id,out=Dxb.id,key=nxb.key,at=os.time(),ev=vxb}
F.log(1,Sme[3551],string.format(Sme[3554],V.name(uxb.id),V.name(Dxb.id),nxb.label,vxb))
F.saveNow()
end
end
function ab.unitLabDone(Wxb)
