end
for ZNb=1,#WNb do
for _Nb=ZNb+1,#WNb do
for aOb,bOb in ipairs(ONb[VNb][WNb[ZNb]])do
for cOb,dOb in ipairs(ONb[VNb][WNb[_Nb]])do
local eOb,fOb=bOb.X-dOb.X,bOb.Z-dOb.Z
local gOb=eOb*eOb+fOb*fOb
if gOb<XNb then
XNb=gOb
end
end
end
end
end
