local wRb,xRb={},{}
for yRb,zRb in pairs(P.simCal)do
local ARb=yRb~=Sme[2047]and not tostring(yRb):find(Sme[3710],1,true)and type(zRb)==Sme[2021]and type(zRb.dmgK)==Sme[2021]and zRb.dmgK or nil
