gb.DMG_SOLVE_LO,gb.DMG_SOLVE_HI,gb.DMG_SOLVE_TRIES=0.1,3,6
function gb.dmgSolve(ZRb,_Rb,aSb,bSb,cSb)
local function dSb(eSb)
local fSb=table.clone(ZRb)
fSb.dmgMul,fSb._dk=eSb,nil
local gSb,hSb=pcall(gb.runRaw,fSb,_Rb,aSb)
if not(gSb and type(hSb)==Sme[2021])then
