local zbc=ubc and ubc.fx
local Abc={}
for Bbc,Cbc in ipairs(vbc or{})do
if V.SUMMONER[Cbc.unit_id]or V.DRONES[Cbc.unit_id]then
table.insert(Abc,(V.name(Cbc.unit_id):gsub(Sme[2759],Sme[942])))
end
end
local Dbc=ubc and(ubc.mapFly or(ubc.flyChance or 0)>0 or(zbc and(zbc.fly or 0)>0))
for Ebc,Fbc in ipairs(vbc or{})do
local Gbc,Hbc=Fbc.unit_id,{}
if V.isFarm(Gbc)then
table.insert(Hbc,Sme[3819])
else
local Ibc=V.allyBuff(Gbc)
if Ibc then
local Jbc,Kbc={},0
for Lbc in pairs(Ibc.types or{})do
table.insert(Jbc,wbc(Lbc))
end
for Mbc,Nbc in ipairs(vbc)do
if Nbc~=Fbc and not V.isFarm(Nbc.unit_id)then
local Obc=V.types(Nbc.unit_id)
for Pbc in pairs(Ibc.types or{})do
if Obc[Pbc]then
Kbc=Kbc+1
break
end
end
end
end
table.sort(Jbc)
table.insert(Hbc,string.format(Sme[3820],#Jbc>0 and table.concat(Jbc,Sme[2294])or Sme[3821],Kbc))
end
if V.BLESS.by[Gbc]and#Abc>0 then
table.insert(Hbc,Sme[3822]..table.concat(Abc,Sme[2133]))
end
if V.SUMMONER[Gbc]then
table.insert(Hbc,Sme[3823])
elseif V.DRONES[Gbc]then
table.insert(Hbc,Sme[3824])
end
local Qbc,Rbc=pcall(V.bleeds,Gbc)
if(ubc and ubc.regen or 0)>0 and Qbc and Rbc then
table.insert(Hbc,string.format(Sme[3825],Rbc))
end
local Sbc,Tbc=pcall(bb.cardAir,Gbc)
if Dbc and Sbc and Tbc then
table.insert(Hbc,Sme[3826])
end
local Ubc,Vbc=V.types(Gbc)
local Wbc,Xbc
for Ybc in pairs(Ubc)do
