if Zbc and(not Wbc or Zbc>Wbc)then
Wbc,Xbc=Zbc,Ybc
end
end
if Wbc then
table.insert(Hbc,string.format(Sme[3827],wbc(Xbc),Wbc))
end
if zbc and zbc.kinds and(tonumber(zbc.kinds[Vbc])or 0)>0 then
table.insert(Hbc,string.format(Sme[3828],wbc(Vbc),math.floor(zbc.kinds[Vbc]*100+0.5)))
end
if ybc.res and ybc.res[Vbc]then
table.insert(Hbc,string.format(Sme[3829],wbc(Vbc),tonumber(ybc.res[Vbc])or 1))
end
if ybc.strong and ybc.strong[Vbc]then
table.insert(Hbc,string.format(Sme[3830],wbc(Vbc)))
end
if#Hbc==0 then
table.insert(Hbc,Sme[3831])
end
local _bc,acc,bcc=pcall(V.mapNudge,Gbc,ubc and ubc.map,ubc and ubc.mapSig)
local ccc=_bc and type(bcc)==Sme[2021]and(tonumber(bcc.n)or 0)or 0
if ccc>0 and ccc<V.MAP_RUNS then
table.insert(Hbc,string.format(Sme[3832],ccc))
