table.insert(Hbc,string.format(Sme[3836],ccc))
end
end
table.insert(xbc,V.name(Gbc)..Sme[2363]..table.concat(Hbc,Sme[2559]))
end
return xbc
end
function gb.explainSave(dcc,ecc,fcc,gcc,hcc,icc,jcc,kcc)
