jb.LUCK_RESERVE=500
jb.MIN_WORTH=0.02
jb.TOP_WORTH=0.08
function jb.shop(Bjc,Cjc)
local Djc=jb.cleared(Bjc)
local Ejc=jb.res(Bjc)
local Fjc=1+0.1*(jb.items(Bjc)._curse_shop or 0)
local Gjc=jb.shopAhead(Bjc)and math.ceil(jb.LUCK_RESERVE*Fjc)or 0
local Hjc={}
local Ijc,Jjc={},0
for Kjc,Ljc in ipairs(jb.offers(Cjc and Cjc.data))do
Ljc.cost=math.ceil(Ljc.cost*Fjc)
table.insert(Ijc,tostring(jb.item(Ljc.id).name or Ljc.id))
if not Ljc.bought and not jb.isCurse(Ljc.id)then
Ljc.luck=tonumber(jb.item(Ljc.id).luck_increase)~=nil
Ljc.v=jb.itemValue(Ljc.id,Bjc)
if not Ljc.luck and Ljc.v/math.max(1,Ljc.cost)<jb.MIN_WORTH then
Jjc=Jjc+1
elseif Ljc.v>0 and(Ljc.luck or Djc>=10 or Ljc.v/math.max(1,Ljc.cost)>=jb.TOP_WORTH)then
table.insert(Hjc,Ljc)
end
end
end
table.sort(Hjc,function(Mjc,Njc)
if Mjc.luck~=Njc.luck then
return Mjc.luck
end
return Mjc.v/math.max(1,Mjc.cost)>Njc.v/math.max(1,Njc.cost)
end)
local Ojc,Pjc,Qjc={},0,0
for Rjc,Sjc in ipairs(Hjc)do
if Sjc.cost<=Ejc-(Sjc.luck and 0 or Gjc)then
if jb.buy(Sjc)then
Ejc=jb.res(jb.data())
table.insert(Ojc,string.format(Sme[3955],tostring(jb.item(Sjc.id).name or Sjc.id),Sjc.cost))
end
elseif Sjc.cost<=Ejc then
Qjc=Qjc+1
else
Pjc=Pjc+1
end
end
jb.note(string.format(Sme[3956],Djc,#Ijc>0 and table.concat(Ijc,Sme[2133])or Sme[3957],#Ojc>0 and(Sme[3958]..table.concat(Ojc,Sme[2133]))or(Djc<10 and Sme[3959]or(Qjc>0 and Sme[3960]or Sme[3961])),Ejc,Pjc>0 and string.format(Sme[3962],Pjc)or Sme[942],Qjc>0 and string.format(Sme[3963],Qjc,Gjc)or Sme[942],Jjc>0 and string.format(Sme[3964],Jjc)or Sme[942]))
F.request(Sme[3965],Sme[3966])
end
function jb.shrine(Tjc,Ujc)
