local Yjc
for Zjc,_jc in ipairs(Vjc)do
local akc=jb.item(_jc.id)
table.insert(Xjc,tostring(akc and akc.name or _jc.id))
if jb.isCurse(_jc.id)then
local bkc,ckc,dkc=pcall(jb.curseOk,_jc.id,Tjc,jb.cleared(Tjc)+1,nil,jb.rooms(Tjc))
if bkc and not ckc then
Yjc=dkc
end
else
Wjc=Wjc+jb.itemValue(_jc.id,Tjc)
end
end
local ekc= #Vjc>0 and Wjc>0 and not Yjc
if ekc then
F.request(Sme[3967],Sme[3968])
else
F.request(Sme[3965],Sme[3966])
end
jb.note(string.format(Sme[3969],#Xjc>0 and table.concat(Xjc,Sme[2133])or Sme[3957],ekc and Sme[3970]or(Yjc and(Sme[3971]..Yjc)or Sme[3972])))
end
function jb.wallet()
local fkc=N.session()and N.session().profile_data or{}
local gkc=fkc.inventory or{}
local hkc={gems=tonumber(N.cur(Sme[2085]))or 0,gold=tonumber(N.cur(Sme[2087]))or 0,items={},units={},unique=0}
