function jb.walletDiff(nkc,okc)
local pkc={}
if okc.gems~=nkc.gems then
table.insert(pkc,string.format(Sme[3973],okc.gems-nkc.gems))
end
if okc.gold~=nkc.gold then
table.insert(pkc,string.format(Sme[3974],okc.gold-nkc.gold))
end
for qkc,rkc in pairs(okc.items)do
if rkc~=(nkc.items[qkc]or 0)then
table.insert(pkc,string.format(Sme[3975],rkc-(nkc.items[qkc]or 0),tostring(qkc)))
end
end
for skc,tkc in pairs(okc.units)do
if not nkc.units[skc]then
table.insert(pkc,Sme[3976]..V.name(tkc))
end
end
if okc.unique~=nkc.unique then
table.insert(pkc,string.format(Sme[3977],okc.unique-nkc.unique))
end
return#pkc>0 and table.concat(pkc,Sme[2133])or Sme[3978]
end
function jb.openChests(ukc,vkc)
local wkc,xkc,ykc=jb.res(ukc)
local zkc=jb.lives(ukc)
local Akc=jb.cleared(ukc)
if not(vkc or Akc>=jb.ROOMS or zkc<=1)then
jb.note(string.format(Sme[3979],Akc,xkc,ykc,jb.luck(ukc)))
F.request(Sme[3965],Sme[3966])
return
end
local Bkc,Ckc,Dkc=0,0,0
local Ekc=tonumber(N.cur(Sme[2085]))or 0
local Fkc=jb.wallet()
for Gkc=1,xkc+ykc+4 do
local Hkc,Ikc,Jkc=jb.res(jb.data())
if Ikc+Jkc<=0 or Dkc>=2 then
break
end
local Kkc,Lkc
if Ikc>0 then
Kkc,Lkc=F.request(Sme[3980],Sme[3981])
else
Kkc,Lkc=F.request(Sme[3980],Sme[3981],true)
end
if Kkc and Lkc~=nil then
F.log(1,Sme[3949],Sme[3982]..(type(Lkc)==Sme[2021]and U.json(U.plain(Lkc)):sub(1,300)or tostring(Lkc)))
end
local Mkc=U.now()
while U.now()-Mkc<4 do
local Nkc,Okc,Pkc=jb.res(jb.data())
if Okc<Ikc or Pkc<Jkc then
break
end
task.wait(0.25)
end
local Qkc,Rkc,Skc=jb.res(jb.data())
if Rkc<Ikc then
Bkc=Bkc+(Ikc-Rkc)
Dkc=0
elseif Skc<Jkc then
Ckc=Ckc+(Jkc-Skc)
Dkc=0
else
Dkc=Dkc+1
end
task.wait(1)
if Rkc<Ikc or Skc<Jkc then
local Tkc=jb.wallet()
local Ukc=jb.walletDiff(Fkc,Tkc)
F.log(1,Sme[3949],(Skc<Jkc and Sme[3983]or Sme[3982])..Ukc)
P.dg.pay=P.dg.pay or{}
local Vkc={}
for Wkc,Xkc in pairs(Tkc.items)do
if Xkc~=(Fkc.items[Wkc]or 0)then
Vkc[Wkc]=Xkc-(Fkc.items[Wkc]or 0)
end
end
table.insert(P.dg.pay,{at=os.time(),rare=Skc<Jkc,gems=Tkc.gems-Fkc.gems,luck=jb.luck(ukc),paid=Ukc,items=Vkc})
while#P.dg.pay>60 do
table.remove(P.dg.pay,1)
end
Fkc=Tkc
end
end
jb.note(string.format(Sme[3984],Bkc,Ckc,vkc and Sme[3985]or(zkc<=1 and Sme[3986]or Sme[3987]),jb.luck(ukc),(tonumber(N.cur(Sme[2085]))or 0)-Ekc))
local Ykc,Zkc,_kc=jb.res(jb.data())
if(vkc or Akc>=jb.ROOMS)and Zkc+_kc>0 then
jb.note(string.format(Sme[3988],Zkc,_kc))
W.rec(Sme[2740]).restUntil=os.time()+1800
return Sme[3989]
end
if not vkc then
F.request(Sme[3965],Sme[3966])
end
end
function jb.act(alc)
