function bb.buildPath()
bb.samples={}
local dpc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not dpc then
return
end
for epc,fpc in pairs(dpc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[epc.Name])then
local gpc={}
for hpc,ipc in ipairs(fpc.points or{})do
table.insert(gpc,ipc.part.Position)
end
local jpc=0
for kpc=2,#gpc do
jpc=jpc+(gpc[kpc]-gpc[kpc-1]).Magnitude
end
local lpc=0
for mpc=2,#gpc do
local npc,opc=gpc[mpc-1],gpc[mpc]
local ppc=(opc-npc).Magnitude
local qpc=math.max(1,math.floor(ppc/2))
for rpc=0,qpc-1 do
local spc=npc:Lerp(opc,rpc/qpc)
table.insert(bb.samples,{pos=spc,prog=(lpc+ppc*rpc/qpc)/math.max(1,jpc),lane=epc.Name})
end
lpc=lpc+ppc
end
if gpc[#gpc]then
table.insert(bb.samples,{pos=gpc[#gpc],prog=1,lane=epc.Name})
end
end
end
pcall(bb.readHidden,dpc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local tpc=tonumber(bb.ld and bb.ld._portal_lanes)
local upc=gb.laneList(bb.samples)
if tpc and tpc>=1 and upc and#upc>tpc then
bb.laneWant=tpc
end
bb.laneTotal=upc and#upc or 1
bb.countLanes()
end
function bb.readHidden(vpc)
local wpc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(wpc)~=Sme[2021]or not next(wpc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local xpc
for ypc,zpc in pairs(vpc)do
if wpc[ypc.Name]and type(zpc.points)==Sme[2021]and#zpc.points>=2 then
local Apc={}
for Bpc,Cpc in ipairs(zpc.points)do
Apc[Bpc]=U.flat(Cpc.part.Position)
end
local Dpc={}
for Epc,Fpc in ipairs(bb.samples)do
local Gpc=tostring(Fpc.lane)
Dpc[Gpc]=Dpc[Gpc]or{}
table.insert(Dpc[Gpc],Fpc)
end
local Hpc,Ipc
for Jpc,Kpc in pairs(Dpc)do
local Lpc=0
for Mpc=1,#Apc,math.max(1,math.floor(#Apc/20))do
local Npc=math.huge
for Opc,Ppc in ipairs(Kpc)do
local Qpc=(U.flat(Ppc.pos)-Apc[Mpc]).Magnitude
if Qpc<Npc then
Npc=Qpc
end
end
Lpc=Lpc+Npc
end
if not Ipc or Lpc<Ipc then
Hpc,Ipc=Jpc,Lpc
end
end
local Rpc,Spc,Tpc,Upc,Vpc,Wpc={},nil,nil,nil,0,0
for Xpc,Ypc in ipairs(Apc)do
local Zpc,_pc=nil,math.huge
for aqc,bqc in ipairs(Dpc[Hpc])do
local cqc=(U.flat(bqc.pos)-Ypc).Magnitude
if cqc<_pc then
_pc,Zpc=cqc,bqc.prog
end
end
Wpc=math.max(Wpc,_pc)
if Tpc then
local dqc=Zpc-Tpc
local eqc=(dqc>0.002 and 1)or(dqc< -0.002 and-1)or Upc
if Upc and eqc and eqc~=Upc then
table.insert(Rpc,math.floor(Tpc*1000+0.5)/1000)
end
Upc,Vpc=eqc or Upc,Vpc+math.abs(dqc)
else
Spc=Zpc
end
Tpc=Zpc
if Xpc%50==0 then
task.wait()
end
end
if Tpc and Wpc<=8 then
table.insert(Rpc,math.floor(Tpc*1000+0.5)/1000)
xpc=xpc or{}
xpc[ypc.Name]={from=math.floor((Spc or 0)*1000+0.5)/1000,len=math.floor(Vpc*1000+0.5)/1000,turns=Rpc,road=Hpc}
end
end
end
if not xpc then
return
end
local fqc=bb.ld.map
P.maps[fqc]=P.maps[fqc]or{}
local gqc=P.maps[fqc].hidden
P.maps[fqc].hidden=xpc
if type(gqc)~=Sme[2021]then
for hqc,iqc in pairs(xpc)do
F.log(1,Sme[2689],string.format(Sme[4077],hqc,iqc.len,tostring(iqc.road),math.floor((#iqc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local jqc,kqc,lqc={},0,0
for mqc,nqc in ipairs(bb.samples)do
local oqc=tostring(nqc.lane)
if not jqc[oqc]then
kqc=kqc+1
end
jqc[oqc]=(jqc[oqc]or 0)+1
lqc=lqc+1
end
bb.laneCount={n=kqc,by=jqc,avg=kqc>0 and lqc/kqc or 1}
if kqc>=2 then
local pqc,qqc=pcall(gb.laneSep,bb.samples)
local rqc=P.maps[bb.mapKey()]
if pqc and qqc and type(rqc)==Sme[2021]then
rqc.sep=qqc
end
end
end
