local Jqc=Hqc and N.Waves[(Iqc and Iqc.template)or Hqc.waves or Hqc.id]
local Kqc
if type(Jqc)==Sme[2021]then
Kqc=Jqc.override_waves or Jqc.waves
if not Kqc and Jqc.template and N.Waves[Jqc.template]then
Kqc=N.Waves[Jqc.template].waves or N.Waves[Jqc.template].override_waves
end
end
bb.waveList=U.list(Kqc)
bb.infinite=Hqc and(Hqc._gamemode==Sme[2040]or Hqc.infinite)and gb.unbound(Hqc)or false
if bb.infinite then
bb.waveList={}
