end
bb.total=(Hqc and type(Hqc._dungeon)==Sme[2021]and 15)or tonumber(Hqc and Hqc._override_infinite_bound_waves)or gb.boundEnd(Hqc,#bb.waveList,bb.key)or(#bb.waveList>0 and#bb.waveList)or 15
end
