end
end
if O.infiniteStop and not bb.stopping and ab.partyRole()~=Sme[3571]and bb.kind~=Sme[2476]then
local Oqc,Pqc=pcall(bb.infStop,Lqc)
if not Oqc then
F.log(1,Sme[2407],Sme[4085]..tostring(Pqc))
end
end
local Qqc=W.infTier(Lqc-1)
if Qqc<=0 or Qqc==bb.infTierSeen then
