end
bb.infTierSeen=Qqc
task.delay(5,function()
if not F.alive then
return
end
local Rqc=N.prof()
local Sqc=Rqc and Rqc.daily_infinite_reward_claims and Rqc.daily_infinite_reward_claims[bb.ld.id]
local Tqc=type(Sqc)==Sme[2021]and(tonumber(Sqc.highest_claimed_wave)or 0)>=Qqc and os.time()-(tonumber(Sqc.highest_claim_time)or 0)<900
if Tqc then
P.infLive=true
