function bb.infStop(Uqc)
local Vqc=0
for Wqc,Xqc in ipairs(U.list(N.GS.DAILY_INFINITE_REWARDS))do
Vqc=math.max(Vqc,tonumber(Xqc.wave)or 0)
end
if Vqc<=0 or Uqc<=Vqc+1 then
return
end
local Yqc=P.train.on
if bb.trainee and Yqc and Yqc.have+(Yqc.got or 0)+(bb.trainTk or 0)<Yqc.need then
return
end
if not ab.every(Sme[4089],60)then
return
end
local Zqc=W.rec(bb.key)
local _qc=tonumber(Zqc.timed)or 0
local arc=W.INF_PAY
local brc
if Uqc>=(arc.cap+arc.less)/arc.per then
brc=0
else
local crc=bb.infWaveAt or{}
local drc,erc=crc[Uqc],crc[Uqc-5]
if drc and erc and drc>erc then
brc=arc.per*5/((drc-erc)/60)
end
if not brc then
brc=(_qc>0 and(Zqc.sec or 0)>0)and math.max(0.5,(Zqc.gems or 0)/(Zqc.sec/60))or 2.5
end
end
local frc=pcall(W.pick)
local grc
for hrc,irc in ipairs(frc and W.lastScored or{})do
if irc.kind~=Sme[2040]and(not grc or(irc.score or 0)>(grc.score or 0))then
grc=irc
end
end
if not grc or(grc.score or 0)<=brc then
return
end
bb.stopping=true
F.log(1,Sme[2689],string.format(Sme[4090],Uqc,brc,grc.score,grc.label))
bb.sellAll()
end
function bb.trainLeave(jrc)
