end
bb.trainCount()
local lrc=krc.have+(krc.got or 0)+(bb.trainTk or 0)
if lrc<krc.need then
return
end
local mrc,nrc,orc=pcall(W.infDaily,N.prof(),bb.ld.id,(W.infReach(bb.key)))
if mrc and(nrc or 0)>0 and orc>0 and jrc<=orc then
F.status(Sme[3241],string.format(Sme[4091],V.name(krc.id),krc.what,orc))
return
end
bb.stopping=true
F.log(1,Sme[2689],string.format(Sme[4092],V.name(krc.id),krc.what,U.fmt(lrc),U.fmt(krc.need),jrc))
bb.sellAll()
end
