function bb.valid(qtc,rtc,stc)
local ttc=N.PC.raycast(qtc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not ttc then
return nil
end
if not N.PC.is_valid_raycast_hit(ttc.Instance,rtc)then
return nil
end
local utc=ttc.Position
if bb.blockedSpot(utc)then
return nil
end
local vtc=(tonumber(rtc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(vtc*2,2.5,vtc*2)
bb.probe.CFrame=CFrame.new(utc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
local wtc=U.flat(utc)
local xtc=bb.grifZone
if xtc and type(rtc)==Sme[2021]and rtc.id~=V.GRIF.egg and not V.sacFodder(rtc.id)and(wtc-xtc.p).Magnitude<=xtc.r+1.5 then
return nil
end
for ytc,ztc in ipairs(bb.mine or{})do
local Atc=ztc:FindFirstChild(Sme[4113])
local Btc=Atc and Atc.Position or ztc:GetPivot().Position
local Ctc=Atc and math.max(Atc.Size.X,Atc.Size.Z)/2 or 1.5
if(wtc-U.flat(Btc)).Magnitude<vtc+Ctc then
return nil
end
end
if not stc then
for Dtc,Etc in ipairs(bb.blockers())do
if(wtc-Etc.p).Magnitude<vtc+Etc.r then
return nil
end
end
end
return utc
end
function bb.buildCandidates()
bb.cands={}
local Ftc={}
for Gtc=1,#bb.samples,3 do
local Htc=bb.samples[Gtc]
local Itc=bb.samples[math.min(#bb.samples,Gtc+1)]
local Jtc=U.flat(Itc.pos-Htc.pos)
if Jtc.Magnitude<0.01 then
Jtc=Vector3 .new(1,0,0)
end
Jtc=Jtc.Unit
local Ktc=Vector3 .new(-Jtc.Z,0,Jtc.X)
for Ltc,Mtc in ipairs({3,4.5,6,8,10.5,13.5,17})do
for Ntc,Otc in ipairs({1,-1})do
local Ptc=Htc.pos+Ktc*Mtc*Otc
local Qtc=string.format(Sme[4110],math.floor(Ptc.X/1.5),math.floor(Ptc.Z/1.5))
if not Ftc[Qtc]then
Ftc[Qtc]=true
table.insert(bb.cands,Ptc)
end
end
end
end
end
function bb.coverage(Rtc,Stc)
local Ttc={}
for Utc,Vtc in ipairs(Rtc)do
local Wtc=Vtc._stats
if not V.isFarm(Wtc.id.Value)and Wtc:FindFirstChild(Sme[2273])then
table.insert(Ttc,{p=U.flat(Vtc:GetPivot().Position),r=Wtc.range.Value*(V.SUMMONER[Wtc.id.Value]and V.SUMMONER[Wtc.id.Value].reach or 1),air=bb.canAir(Vtc)})
end
end
local Xtc,Ytc=0,0
if#Ttc>0 then
for Ztc,_tc in ipairs(bb.samples)do
if _tc.prog>Ytc then
local auc=U.flat(_tc.pos)
for buc,cuc in ipairs(Ttc)do
if(auc-cuc.p).Magnitude<=cuc.r then
if _tc.prog>Xtc then
Xtc=_tc.prog
end
if cuc.air then
Ytc=_tc.prog
break
end
end
end
end
end
end
local duc,euc={},bb.laneCount
if euc and euc.n>=2 and#Ttc>0 then
local fuc={}
for guc,huc in ipairs(bb.samples)do
local iuc=U.flat(huc.pos)
for juc,kuc in ipairs(Ttc)do
if(iuc-kuc.p).Magnitude<=kuc.r then
local luc=tostring(huc.lane)
fuc[luc]=(fuc[luc]or 0)+1
if huc.prog>(duc[luc]or 0)then
duc[luc]=huc.prog
end
break
end
end
end
local muc,nuc={},0
for ouc,puc in pairs(euc.by)do
muc[ouc]=(fuc[ouc]or 0)/math.max(1,puc)
nuc=math.max(nuc,muc[ouc])
end
bb.laneW={}
for quc,ruc in pairs(euc.by)do
bb.laneW[quc]=(euc.avg/math.max(1,ruc))*(1+1.5*(nuc>0 and(1-muc[quc]/nuc)or 0))
end
bb.laneFrac=muc
else
bb.laneW,bb.laneFrac=nil,nil
end
local suc,tuc,uuc
if#Ttc>0 then
for vuc,wuc in ipairs(Stc)do
local xuc=(bb.laneW and wuc.lane)and(duc[tostring(wuc.lane)]or 0)or Xtc
if wuc.hp>0 and wuc.prog>xuc+0.02 and wuc.prog>(suc or 0)then
suc,uuc=wuc.prog,bb.laneW and wuc.lane or nil
end
if wuc.hp>0 and wuc.fly and wuc.prog>Ytc+0.02 then
tuc=true
end
end
end
local yuc= #Ttc>0 and(bb.pressure or 0)>=Xtc-0.08
return{covEnd=Xtc,airEnd=Ytc,leak=suc,leakLane=uuc,covL=duc,airLeak=tuc,push=yuc,units= #Ttc}
end
function bb.needLastLine(zuc)
if V.isFarm(zuc.id)or V.allyBuff(zuc.id)or bb.fieldCount()<5 then
return false
end
local Auc,Buc=0,0
for Cuc,Duc in ipairs(bb.mine or{})do
local Euc=Duc._stats
if not V.isFarm(Euc.id.Value)and Euc:FindFirstChild(Sme[2273])then
local Fuc,Guc=U.flat(Duc:GetPivot().Position),Euc.range.Value
for Huc,Iuc in ipairs(bb.samples)do
if Iuc.prog>=0.85 and(U.flat(Iuc.pos)-Fuc).Magnitude<=Guc then
Auc=Auc+1
if bb.canAir(Duc)then
Buc=Buc+1
end
break
end
end
end
end
return Auc<2 or(Buc<1 and bb.flyMode()and bb.cardAir(zuc.id))
end
bb.airCache=setmetatable({},{__mode=Sme[2406]})
function bb.canAir(Juc)
local Kuc=Juc._stats:FindFirstChild(Sme[2112])and Juc._stats.upgrade.Value or 0
