function bb.studyMoves(JIc,KIc)
local LIc=V.rows(JIc.id)
local MIc=V.range(JIc.e.u,LIc.max)*KIc
local NIc=MIc*MIc
local OIc,PIc={},{}
local QIc,RIc=bb.hurtSamples(),bb.sandLine()
for SIc,TIc in ipairs(JIc.spots or{})do
local UIc,VIc,WIc,XIc,YIc=0,0,0,0,0
for ZIc,_Ic in ipairs(QIc)do
local aJc,bJc=_Ic.pos.X-TIc.X,_Ic.pos.Z-TIc.Z
if aJc*aJc+bJc*bJc<=NIc then
WIc=WIc+1
local cJc=math.min(49,math.floor(_Ic.prog*50))
if cJc<25 then
UIc=bit32 .bor(UIc,bit32 .lshift(1,cJc))
else
VIc=bit32 .bor(VIc,bit32 .lshift(1,cJc-25))
end
if _Ic.prog-RIc<=0.3 then
XIc=XIc+1
elseif _Ic.prog>=0.7 then
YIc=YIc+1
end
end
end
if WIc>0 then
local dJc=UIc..Sme[2156]..VIc
local eJc=OIc[dJc]
if not eJc then
eJc={p=TIc,lo=UIc,hi=VIc,n=WIc,early=XIc,late=YIc}
OIc[dJc]=eJc
table.insert(PIc,eJc)
elseif WIc>eJc.n then
eJc.p,eJc.n,eJc.early,eJc.late=TIc,WIc,XIc,YIc
end
end
if SIc%40==0 then
task.wait()
end
end
local fJc={}
for gJc,hJc in ipairs(PIc)do
local iJc=false
for jJc,kJc in ipairs(PIc)do
if gJc~=jJc and kJc.n>=hJc.n and bit32 .band(hJc.lo,kJc.lo)==hJc.lo and bit32 .band(hJc.hi,kJc.hi)==hJc.hi and(kJc.lo~=hJc.lo or kJc.hi~=hJc.hi or kJc.n>hJc.n)then
iJc=true
break
end
end
if not iJc then
table.insert(fJc,hJc)
end
if gJc%40==0 then
task.wait()
end
end
local lJc,mJc={},{}
local function nJc(oJc)
if oJc and not mJc[oJc]then
mJc[oJc]=true
table.insert(lJc,oJc)
end
end
table.sort(fJc,function(pJc,qJc)
return pJc.n>qJc.n
end)
for rJc=1,math.min(bb.STUDY_K,#fJc)do
nJc(fJc[rJc].p)
end
table.sort(fJc,function(sJc,tJc)
return sJc.early>tJc.early
end)
nJc(fJc[1]and fJc[1].p)
nJc(fJc[2]and fJc[2].p)
table.sort(fJc,function(uJc,vJc)
return uJc.late>vJc.late
end)
nJc(fJc[1]and fJc[1].p)
nJc(fJc[2]and fJc[2].p)
local wJc=0
for xJc,yJc in ipairs((bb.hiveUnitSpots(bb.ld and bb.ld.map,JIc.id)))do
local zJc=tonumber(yJc.x)and tonumber(yJc.z)and bb.nearSpot(JIc.spots,tonumber(yJc.x),tonumber(yJc.z))or nil
if zJc and not mJc[zJc]then
nJc(zJc)
wJc=wJc+1
end
end
for AJc,BJc in ipairs(bb.hiveSpots(bb.ld and bb.ld.map))do
if wJc>=bb.STUDY_SHARED then
break
end
local CJc=false
for DJc,EJc in ipairs(type(BJc.units)==Sme[2021]and BJc.units or{})do
local FJc=EJc==JIc.id and MIc or((bb.baseRange(EJc)or 0)*KIc)
if EJc==JIc.id or(FJc>0 and math.abs(FJc-MIc)<=0.3*MIc)then
CJc=true
break
end
end
local GJc=CJc and tonumber(BJc.x)and tonumber(BJc.z)and bb.nearSpot(JIc.spots,tonumber(BJc.x),tonumber(BJc.z))or nil
if GJc and not mJc[GJc]then
nJc(GJc)
wJc=wJc+1
end
end
return lJc,#PIc,#fJc,wJc
end
function bb.studyRun(HJc)
local IJc=U.now()
