local function lKc(mKc)
local nKc,oKc,pKc=0,0,0
for qKc,rKc in ipairs(PJc)do
local sKc=os.clock()
local tKc=gb.runRaw(KJc,LJc,{hpMul=rKc,layout=dKc(mKc),bg=true})
nKc,oKc,pKc=nKc+gb.objective(tKc),oKc+(tonumber(tKc.kills)or 0),pKc+(tonumber(tKc.wave)or 0)
task.wait(math.clamp((os.clock()-sKc)*3,0.25,HJc.pauseMax or 1.5))
if not JJc()then
