local LKc=type(KKc)==Sme[2021]and tonumber(KKc[1])and tonumber(KKc[3])and bb.nearSpot(JKc.spots,tonumber(KKc[1]),tonumber(KKc[3]))or nil
if LKc and LKc~=GKc[JKc.id]and not zKc(GKc,JKc.id,LKc)then
