local UKc={FKc}
for VKc,WKc in ipairs(HJc.attackers)do
local XKc={}
for YKc,ZKc in ipairs(UKc)do
table.insert(XKc,ZKc)
for _Kc,aLc in ipairs(SJc[WKc.id]or{})do
