function bb.validOpen(uLc,vLc)
local wLc=N.PC.raycast(uLc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not wLc then
return nil
end
if not N.PC.is_valid_raycast_hit(wLc.Instance,vLc)then
return nil
end
local xLc=wLc.Position
if bb.blockedSpot(xLc)then
return nil
end
local yLc=(tonumber(vLc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(yLc*2,2.5,yLc*2)
bb.probe.CFrame=CFrame.new(xLc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return xLc
end
function bb.studyInfinite()
if O.mapStudy==false or not(bb.info and bb.infinite)or bb.kind==Sme[2476]then
return
end
local zLc=bb.info
local function ALc()
