local fMc={info=zLc,team=gb.teamFrom(BLc,zLc.map),key=bb.bookKey(zLc),hard=1,scale=tonumber(zLc.rangeScale)or 1,attackers={},pauseMax=4,inf=true}
local gMc={spots={},style=Sme[2961],hybridHill=bb.hybridHill and true or false}
for hMc,iMc in ipairs(CLc)do
