end
return string.format(Sme[4257],tostring(nMc.label),tonumber(nMc.n)or 0,tonumber(nMc.run)or 0,oMc(nMc.bestKills,nMc.bestWave),oMc(nMc.baseKills,nMc.baseWave),(nMc.better or 0)>0 and Sme[4258]or Sme[942])
