function bb.bookSave(rMc,sMc,tMc,uMc)
P.mapBook=type(P.mapBook)==Sme[2021]and P.mapBook or{}
local vMc={}
for wMc,xMc in pairs(tMc.spots or{})do
vMc[wMc]={math.floor(xMc.X*10+0.5)/10,math.floor(xMc.Y*10+0.5)/10,math.floor(xMc.Z*10+0.5)/10}
end
P.mapBook[sMc.key]={spots=vMc,style=sMc.base.style,hp=uMc.hp,n=uMc.n,kills=tMc.kills and math.floor(tMc.kills+0.5)or nil,wave=tMc.wave and math.floor(tMc.wave*10+0.5)/10 or nil,base=uMc.baseWave and math.floor(uMc.baseWave*10+0.5)/10 or nil,label=uMc.label,map=rMc.map,killScore=uMc.kills,at=os.time()}
local yMc={}
for zMc,AMc in pairs(P.mapBook)do
table.insert(yMc,{k=zMc,at=type(AMc)==Sme[2021]and tonumber(AMc.at)or 0})
end
if#yMc>bb.BOOK_MAX then
table.sort(yMc,function(BMc,CMc)
return BMc.at>CMc.at
end)
for DMc=bb.BOOK_MAX+1,#yMc do
P.mapBook[yMc[DMc].k]=nil
end
end
F.saveSoon()
end
function bb.studyEnd(EMc,FMc,GMc)
if type(EMc)~=Sme[2021]or EMc.ended then
return
end
EMc.ended=true
if GMc and FMc then
local HMc=bb.bookFor(FMc.info)
if HMc then
HMc.n=EMc.n
F.saveSoon()
elseif EMc.run>0 then
pcall(bb.bookSave,FMc.info,FMc,GMc,EMc)
end
end
if EMc.run>0 then
F.log(1,Sme[2774],bb.studyWords(EMc))
end
end
function bb.studyReport()
