local JMc={}
for KMc,LMc in pairs(IMc.spots)do
if type(LMc)==Sme[2021]then
JMc[KMc]={LMc[1],LMc[3]}
end
end
return{n=IMc.n,kills=IMc.kills,wave=IMc.wave,hp=IMc.hp,spots=JMc}
end
function bb.studyText()
if O.mapStudy==false then
return Sme[3090]
end
if F.where==Sme[2093]and type(bb.study)==Sme[2021]and not bb.study.ended then
return Sme[4259]..bb.studyWords(bb.study)
end
local MMc,NMc,OMc=0,nil,0
for PMc,QMc in pairs(type(P.mapBook)==Sme[2021]and P.mapBook or{})do
if type(QMc)==Sme[2021]then
MMc=MMc+1
if(tonumber(QMc.at)or 0)>OMc then
NMc,OMc=QMc,tonumber(QMc.at)or 0
end
end
end
if MMc==0 then
return Sme[4260]
end
return string.format(Sme[4261],MMc,tostring(NMc.label),tonumber(NMc.n)or 0,NMc.killScore and string.format(Sme[4195],tonumber(NMc.kills)or 0)or string.format(Sme[4262],tostring(NMc.wave)))
end
function bb.spotResult(RMc,SMc)
if not(bb.info and bb.info.timeLimit)then
for TMc,UMc in pairs(bb.layoutUsed or{})do
local VMc=bb.spotRec(TMc,UMc,true)
VMc.runs,VMc.wins=(tonumber(VMc.runs)or 0)+1,(tonumber(VMc.wins)or 0)+(RMc and 1 or 0)
end
end
local WMc,XMc=pcall(bb.labRecord,RMc,SMc)
if not WMc then
F.log(1,Sme[2407],Sme[4249]..tostring(XMc))
end
local YMc,ZMc=pcall(bb.layoutResult,RMc,SMc)
if not YMc then
F.log(1,Sme[2407],Sme[4263]..tostring(ZMc))
end
if not bb.infinite then
bb.styleRecord(RMc)
end
end
bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3600,0.015,300
bb.HIVE_TRY_EVERY,bb.HIVE_TRIALS=3,3
function bb.layoutRecFor(_Mc,aNc)
local bNc=bb.bookKey(_Mc)
P.layoutRec=type(P.layoutRec)==Sme[2021]and P.layoutRec or{}
local cNc=P.layoutRec[bNc]
if type(cNc)~=Sme[2021]then
if not aNc then
return nil
end
cNc={at=os.time()}
P.layoutRec[bNc]=cNc
if U.count(P.layoutRec)>80 then
local dNc,eNc
for fNc,gNc in pairs(P.layoutRec)do
local hNc=type(gNc)==Sme[2021]and tonumber(gNc.at)or 0
if not eNc or hNc<eNc then
dNc,eNc=fNc,hNc
end
end
P.layoutRec[dNc]=nil
end
end
return cNc
end
function bb.layoutAdd(iNc,jNc,kNc,lNc,mNc)
iNc.runs,iNc.wins=(tonumber(iNc.runs)or 0)+1,(tonumber(iNc.wins)or 0)+(jNc and 1 or 0)
iNc.sec,iNc.wave=type(iNc.sec)==Sme[2021]and iNc.sec or{},type(iNc.wave)==Sme[2021]and iNc.wave or{}
if jNc and tonumber(kNc)then
table.insert(iNc.sec,math.floor(kNc+0.5))
end
table.insert(iNc.wave,tonumber(lNc)or 0)
if tonumber(mNc)then
iNc.kills=type(iNc.kills)==Sme[2021]and iNc.kills or{}
table.insert(iNc.kills,math.floor(tonumber(mNc)))
while#iNc.kills>bb.LAYOUT_KEEP do
table.remove(iNc.kills,1)
end
end
while#iNc.sec>bb.LAYOUT_KEEP do
table.remove(iNc.sec,1)
end
while#iNc.wave>bb.LAYOUT_KEEP do
table.remove(iNc.wave,1)
end
end
function bb.layoutJudge(nNc,oNc,pNc,qNc,rNc)
rNc=rNc or Sme[4264]
local sNc,tNc=tonumber(nNc and nNc.runs)or 0,tonumber(oNc and oNc.runs)or 0
if sNc<1 or tNc<bb.LAYOUT_CONTROL then
return nil
end
if qNc and type(nNc.kills)==Sme[2021]and type(oNc.kills)==Sme[2021]and#nNc.kills>=1 and#oNc.kills>=bb.LAYOUT_CONTROL then
local uNc,vNc=bb.labMedian(nNc.kills),bb.labMedian(oNc.kills)
if uNc and vNc and uNc<vNc*0.97 and(#nNc.kills>=2 or uNc<vNc*0.85)then
return string.format(Sme[4265],uNc,vNc,rNc)
end
return nil
end
local wNc,xNc=(tonumber(nNc.wins)or 0)/sNc,(tonumber(oNc.wins)or 0)/tNc
if not pNc and xNc>=0.5 then
if wNc+0.25<xNc and(sNc>=2 or(wNc==0 and xNc>=0.9 and tNc>=3))then
return string.format(Sme[4266],tonumber(nNc.wins)or 0,sNc,sNc==1 and Sme[942]or Sme[1869],tonumber(oNc.wins)or 0,tNc,rNc)
end
local yNc,zNc=bb.labMedian(nNc.sec),bb.labMedian(oNc.sec)
if yNc and zNc and yNc>zNc*1.10 and(#nNc.sec>=2 or yNc>zNc*1.25)then
return string.format(Sme[4267],math.floor(yNc/60),yNc%60,math.floor(zNc/60),zNc%60,rNc)
end
return nil
end
local ANc,BNc=bb.labMedian(nNc.wave),bb.labMedian(oNc.wave)
if ANc and BNc and ANc<BNc-math.max(1,BNc*0.03)and(sNc>=2 or ANc<BNc*0.85)then
return string.format(Sme[4268],ANc,BNc,rNc)
end
return nil
end
function bb.layoutResult(CNc,DNc)
local ENc=bb.info
local FNc=bb.layoutSrc
if not(ENc and FNc)or bb.labTest or bb.withOthers or bb.fastAlways then
return
end
if bb.infinite and not ENc.timeLimit then
return
end
local GNc=bb.wave()
local HNc=bb.layoutRecFor(ENc,true)
HNc.at=os.time()
local INc=ENc.timeLimit~=nil
local JNc=ENc.killScore and true or nil
local KNc=JNc and(bb.killsEnd or bb.realKills())or nil
if FNc==Sme[4234]then
local LNc=bb.bookFor(ENc)
if not LNc then
return
end
LNc.real=type(LNc.real)==Sme[2021]and LNc.real or{}
bb.layoutAdd(LNc.real,CNc,DNc,GNc,KNc)
local MNc=LNc.aside==nil and bb.layoutJudge(LNc.real,HNc.own,INc,JNc)or nil
if MNc then
LNc.aside={at=os.time(),why=MNc}
F.log(1,Sme[4178],string.format(Sme[4269],MNc))
end
elseif FNc==Sme[3613]then
HNc.hiveUnit=type(HNc.hiveUnit)==Sme[2021]and HNc.hiveUnit or{}
local NNc=HNc.hiveUnit
bb.layoutAdd(NNc,CNc,DNc,GNc,KNc)
local ONc=bb.bookFor(ENc)
local PNc=ONc and type(ONc.real)==Sme[2021]and(tonumber(ONc.real.runs)or 0)>=bb.LAYOUT_CONTROL
local QNc=PNc and ONc.real or HNc.own
local RNc=bb.layoutJudge(NNc,QNc,INc,JNc,PNc and Sme[4270]or nil)
if RNc then
NNc.aside,NNc.why=os.time(),RNc
F.log(1,Sme[4178],string.format(Sme[4271],RNc))
elseif(tonumber(NNc.runs)or 0)>=bb.HIVE_TRIALS then
local SNc=QNc and bb.layoutJudge(QNc,NNc,INc,JNc,Sme[4272])
if SNc and ONc and type(bb.hiveUnitPlan)==Sme[2021]then
for TNc,UNc in pairs(bb.hiveUnitPlan)do
ONc.spots[TNc]=UNc
end
ONc.real={runs=NNc.runs,wins=NNc.wins,sec=NNc.sec,wave=NNc.wave,kills=NNc.kills}
ONc.hive,ONc.aside=os.time(),nil
HNc.hiveUnit=nil
F.log(1,Sme[4178],string.format(Sme[4273],SNc))
else
NNc.aside,NNc.why=os.time(),Sme[4274]
F.log(1,Sme[4178],Sme[4275])
end
end
else
HNc[FNc]=type(HNc[FNc])==Sme[2021]and HNc[FNc]or{}
local VNc=HNc[FNc]
bb.layoutAdd(VNc,CNc,DNc,GNc,KNc)
if FNc==Sme[3612]and VNc.aside==nil then
local WNc=bb.layoutJudge(VNc,HNc.own,INc,JNc)
if WNc then
VNc.aside,VNc.why=os.time(),WNc
F.log(1,Sme[4178],string.format(Sme[4276],WNc))
end
end
end
F.saveSoon()
end
bb.CONTROL_WORDS={Sme[4277],Sme[4278],Sme[4279],Sme[4280]}
function bb.controlSpot(XNc,YNc)
if not bb.killZone()then
return nil
end
local ZNc=gb.holds
if not ZNc(XNc.id)or V.toggleOf(XNc.id)then
return nil
end
local _Nc,aOc,bOc,cOc=1,0,0,{}
local dOc=bb.hurtSamples()
for eOc,fOc in ipairs(bb.mine or{})do
local gOc=fOc._stats
local hOc=gOc.id.Value
if gOc:FindFirstChild(Sme[2273])and not V.isFarm(hOc)and not V.allyBuff(hOc)then
local iOc,jOc=U.flat(fOc:GetPivot().Position),gOc.range.Value
if ZNc(hOc)and not V.toggleOf(hOc)then
bOc=bOc+1
table.insert(cOc,{p=iOc,r=jOc})
else
for kOc,lOc in ipairs(dOc)do
if(U.flat(lOc.pos)-iOc).Magnitude<=jOc then
_Nc,aOc=math.min(_Nc,lOc.prog),math.max(aOc,lOc.prog)
end
end
end
end
end
if aOc<=_Nc then
_Nc,aOc=0.75,0.98
end
local mOc=(YNc or bOc)+1
local nOc=({_Nc,aOc,(_Nc+aOc)/2,_Nc-(aOc-_Nc)/2})[mOc]
if not nOc then
return nil
end
local oOc=V.range(XNc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local pOc={}
for qOc,rOc in ipairs(bb.cands)do
local sOc,tOc,uOc=U.flat(rOc),0,0
for vOc,wOc in ipairs(dOc)do
if(U.flat(wOc.pos)-sOc).Magnitude<=oOc then
uOc=uOc+1
if math.abs(wOc.prog-nOc)<=0.05 then
tOc=tOc+1
local xOc=U.flat(wOc.pos)
for yOc,zOc in ipairs(cOc)do
if(xOc-zOc.p).Magnitude<=zOc.r then
tOc=tOc-0.5
break
end
end
end
end
end
if tOc>0 then
table.insert(pOc,{pos=rOc,sc=tOc,cov=uOc})
end
if qOc%60==0 then
task.wait()
end
end
table.sort(pOc,function(AOc,BOc)
return AOc.sc>BOc.sc
end)
for COc,DOc in ipairs(pOc)do
local EOc=bb.valid(DOc.pos,XNc.data)
if EOc then
F.log(1,Sme[4117],string.format(Sme[4281],V.name(XNc.id),bb.CONTROL_WORDS[mOc],math.floor(nOc*100+0.5)))
return EOc,DOc.cov,nOc
end
if COc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(FOc)
local GOc,HOc=gb.holds(FOc.id)
if not GOc then
return nil
end
if V.killFed(FOc.id)then
return nil
end
local IOc,JOc={},0
for KOc,LOc in ipairs(bb.mine or{})do
local MOc=LOc._stats
local NOc=MOc.id.Value
if MOc:FindFirstChild(Sme[2273])and not V.isFarm(NOc)and not V.allyBuff(NOc)and NOc~=FOc.id then
local OOc,POc=pcall(bb.liveDps,LOc,NOc)
POc=OOc and tonumber(POc)or 0
if POc>0 then
table.insert(IOc,{p=U.flat(LOc:GetPivot().Position),r=MOc.range.Value,d=POc})
JOc=JOc+POc
end
end
end
if#IOc==0 or JOc<=0 then
return nil
end
local QOc=bb.hurtSamples()
local ROc={}
for SOc,TOc in ipairs(QOc)do
local UOc,VOc=U.flat(TOc.pos),0
for WOc,XOc in ipairs(IOc)do
if(UOc-XOc.p).Magnitude<=XOc.r then
VOc=VOc+XOc.d
end
end
ROc[SOc]=VOc/JOc
end
local YOc=V.range(FOc.u,math.min(tonumber(HOc)or 0,3,V.rows(FOc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local ZOc,_Oc,aPc
for bPc,cPc in ipairs(bb.cands)do
local dPc,ePc,fPc=U.flat(cPc),0,0
for gPc,hPc in ipairs(QOc)do
if(U.flat(hPc.pos)-dPc).Magnitude<=YOc then
ePc=ePc+ROc[gPc]
fPc=fPc+1
end
end
if ePc>0 and(not _Oc or ePc>_Oc)then
local iPc=bb.valid(cPc,FOc.data)
if iPc then
ZOc,_Oc,aPc=iPc,ePc,fPc
end
end
if bPc%40==0 then
task.wait()
end
end
if not ZOc then
return nil
end
bb.holdSaid=bb.holdSaid or{}
if not bb.holdSaid[FOc.id]then
bb.holdSaid[FOc.id]=true
F.log(1,Sme[4117],string.format(Sme[4282],V.name(FOc.id)))
end
return ZOc,aPc or 0
end
function bb.bestSpot(jPc,kPc,lPc)
if(jPc._grif or jPc.id==V.GRIF.egg)and not lPc and bb.grifOn()then
local mPc,nPc,oPc=pcall(bb.grifSpot,jPc)
if mPc and nPc then
return nPc,oPc
end
if not mPc and ab.every(Sme[4283],30)then
F.log(1,Sme[2407],Sme[4284]..tostring(nPc))
end
if jPc._grif then
return nil,0
end
end
if bb.hybridHill and not jPc._hillTry and type(jPc.data)==Sme[2021]and jPc.data.hybrid_placement and not jPc.data.hill_unit then
local pPc=setmetatable({data=bb.hillData(jPc.data),_hillTry=true},{__index=jPc})
local qPc,rPc,sPc=pcall(bb.bestSpot,pPc,kPc,lPc)
if qPc and rPc then
return rPc,sPc
end
end
if bb.focus and not kPc and not lPc and not V.allyBuff(jPc.id)then
local tPc,uPc=bb.focusSpot(jPc)
if tPc then
return tPc,uPc
end
end
if O.fishiFollow and not kPc and not lPc then
local vPc,wPc,xPc,yPc,zPc=pcall(bb.drownBoss)
if vPc and wPc and not xPc and zPc and zPc[jPc.id]then
local APc,BPc,CPc=pcall(bb.drownSpot,jPc,wPc)
if APc and BPc then
return BPc,CPc
end
end
end
if not kPc and not lPc and not(bb.depth and bb.depth.leak)then
local DPc,EPc,FPc=pcall(bb.controlSpot,jPc)
if DPc and EPc then
return EPc,FPc
end
local GPc,HPc,IPc=pcall(bb.holdSpot,jPc)
if GPc and HPc then
return HPc,IPc
end
end
local JPc=bb.depth and bb.depth.leak
if bb.layout and bb.layout[jPc.id]and not kPc and not lPc then
local KPc=false
for LPc,MPc in ipairs(bb.mine or{})do
local NPc=MPc._stats:FindFirstChild(Sme[2397])
if NPc and NPc.Value==jPc.uuid then
KPc=true
break
end
end
if not KPc then
for OPc,PPc in ipairs(bb.layout[jPc.id])do
local QPc=bb.valid(PPc,jPc.data)
if QPc and bb.sandLine()>0 and bb.cover(QPc,V.range(jPc.u,V.rows(jPc.id).max)*((bb.info and tonumber(bb.info.rangeScale))or 1))<=0 then
QPc=nil
end
if QPc and JPc then
local RPc,SPc,TPc=false,U.flat(QPc),V.range(jPc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local UPc=bb.depth and bb.depth.leakLane and tostring(bb.depth.leakLane)or nil
for VPc,WPc in ipairs(bb.hurtSamples())do
if WPc.prog>=JPc+0.02 and(not UPc or tostring(WPc.lane)==UPc)and(U.flat(WPc.pos)-SPc).Magnitude<=TPc then
RPc=true
break
end
end
if not RPc then
QPc=nil
end
end
if QPc then
bb.layoutUsed=bb.layoutUsed or{}
bb.layoutUsed[jPc.id]=QPc
return QPc,bb.cover(QPc,V.range(jPc.u,math.min(3,V.rows(jPc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1))
end
end
end
end
local XPc=jPc.data
local YPc=bb.depth
local ZPc,_Pc=bb.hurtSamples(),bb.sandLine()
local aQc
if lPc then
aQc=1
for bQc,cQc in ipairs(bb.mine or{})do
local dQc=cQc._stats
if not V.isFarm(dQc.id.Value)and not(dQc:FindFirstChild(Sme[2397])and dQc.uuid.Value==jPc.uuid)then
local eQc,fQc=U.flat(cQc:GetPivot().Position),dQc.range.Value
for gQc,hQc in ipairs(ZPc)do
if hQc.prog<aQc and(U.flat(hQc.pos)-eQc).Magnitude<=fQc then
aQc=hQc.prog
end
end
end
end
if V.ENTRY[jPc.id]or(bb.studyEntry and jPc.id==bb.trialId)then
aQc=math.min(aQc,_Pc+0.1)
end
end
local iQc=(bb.info and tonumber(bb.info.rangeScale))or 1
local jQc=V.range(jPc.u,(YPc and YPc.leak)and 0 or math.min(3,V.rows(jPc.id).max))*iQc
local kQc=(bb.kind==Sme[2041]or bb.style==Sme[3713]or bb.style==Sme[3714])and not kPc and not(YPc and YPc.leak)and not V.isFarm(jPc.id)and V.range(jPc.u,V.rows(jPc.id).max)*iQc or nil
local lQc=V.allyBuff(jPc.id)
if bb.killZone()and not kPc and not lPc and not lQc and not(YPc and YPc.leak)and not V.isFarm(jPc.id)then
local mQc=kQc or jQc
local nQc={}
for oQc,pQc in ipairs(bb.mine or{})do
local qQc=pQc._stats
local rQc=qQc.id.Value
if not V.isFarm(rQc)and not V.allyBuff(rQc)and qQc:FindFirstChild(Sme[2273])then
table.insert(nQc,{p=U.flat(pQc:GetPivot().Position),r=qQc.range.Value})
end
end
local sQc={}
for tQc,uQc in ipairs(ZPc)do
local vQc=0
local wQc=U.flat(uQc.pos)
for xQc,yQc in ipairs(nQc)do
if(wQc-yQc.p).Magnitude<=yQc.r then
vQc=vQc+1
end
end
sQc[tQc]=vQc
end
local zQc,AQc,BQc
local CQc=0
for DQc,EQc in ipairs(bb.cands)do
local FQc=bb.valid(EQc,XPc)
CQc=CQc+1
if CQc%40==0 then
task.wait()
end
if FQc then
local GQc,HQc,IQc=U.flat(FQc),0,0
for JQc,KQc in ipairs(ZPc)do
if(U.flat(KQc.pos)-GQc).Magnitude<=mQc then
IQc=IQc+1
if KQc.prog>=0.6 then
HQc=HQc+(KQc.prog-0.5)*(1+sQc[JQc])
end
end
end
if not AQc or HQc>AQc then
zQc,AQc,BQc=FQc,HQc,IQc
end
end
end
if zQc and AQc>0 then
if not bb.zoneSaid then
bb.zoneSaid=true
F.log(1,Sme[4117],Sme[4285])
end
return zQc,BQc or 0
end
end
if bb.style==Sme[3714]and not kPc and not lPc and not lQc and not(YPc and YPc.leak)and not V.isFarm(jPc.id)then
local LQc=kQc or jQc
local MQc,NQc,OQc
local PQc=0
for QQc,RQc in ipairs(bb.cands)do
local SQc=bb.valid(RQc,XPc)
PQc=PQc+1
if PQc%40==0 then
task.wait()
end
if SQc then
local TQc,UQc,VQc=U.flat(SQc),0,0
for WQc,XQc in ipairs(ZPc)do
if(U.flat(XQc.pos)-TQc).Magnitude<=LQc then
VQc=VQc+1
if XQc.prog-_Pc<=bb.FAST_ROAD then
UQc=UQc+1.5-(XQc.prog-_Pc)
end
end
end
if not NQc or UQc>NQc then
MQc,NQc,OQc=SQc,UQc,VQc
end
end
end
if MQc and NQc>0 then
return MQc,OQc or 0
end
end
local YQc=bb.infinite and bb.trainee and not lPc and jPc.uuid~=bb.trainee and not V.isFarm(jPc.id)and not lQc and not kPc and not(YPc and YPc.leak)and(bb.pressure or 0)<O.dangerReach and ib.ZONE or nil
local ZQc=YQc and V.range(jPc.u,V.rows(jPc.id).max)or nil
local _Qc,aRc=V.types(jPc.id)
local bRc=lQc and{}or bb.fieldBuffers()
local cRc,dRc={},0
if lQc then
cRc=bb.buffShort(lQc)
local eRc=false
if V.stackCap(lQc.attack)then
for fRc,gRc in ipairs(cRc)do
if gRc.n>0 then
eRc=true
break
end
end
end
for hRc,iRc in ipairs(cRc)do
iRc.w=(eRc and iRc.n==0)and 0.1 or 1
dRc=dRc+iRc.full*iRc.w
end
end
local jRc=O.community and not aQc and N.TIPS[jPc.id]
local kRc=((jRc and jRc.spot==Sme[2009])or(not aQc and bb.needLastLine(jPc)))and not(YPc and YPc.leak)
local lRc=not(aQc or kPc or lQc)and bb.mergeSpot(jPc)
local mRc=lRc and V.range(jPc.u,0)*0.7
local nRc,oRc
if kPc and V.isFarm(jPc.id)then
nRc,oRc=bb.farmMergeSpot(jPc)
oRc=nRc and oRc*0.8
end
local pRc=kPc and not nRc and bb.random and V.isFarm(jPc.id)and bb.farmMergeOk()and{}or nil
local qRc=bb.cands
local rRc,sRc=nRc or lRc,nRc and oRc or mRc
if rRc and sRc and sRc>0 then
qRc=table.clone(bb.cands)
for tRc,uRc in ipairs({0.5,0.7,0.9})do
for vRc=0,11 do
local wRc=vRc*math.pi/6
table.insert(qRc,rRc+Vector3 .new(math.cos(wRc),0,math.sin(wRc))*sRc*uRc)
end
end
end
local xRc,yRc,zRc
local ARc=0
local BRc=P.maps[bb.mapKey()]and P.maps[bb.mapKey()].dens
for CRc,DRc in ipairs(qRc)do
local ERc=bb.valid(DRc,XPc)
ARc=ARc+1
if ARc%40==0 then
task.wait()
end
if ERc then
local FRc
if kPc then
FRc= -bb.cover(ERc,jQc)
elseif aQc then
FRc=0
local GRc=U.flat(ERc)
for HRc,IRc in ipairs(ZPc)do
if(U.flat(IRc.pos)-GRc).Magnitude<=jQc then
FRc=FRc+(IRc.prog<=aQc+0.05 and 1 or 0.1)
end
end
elseif YQc then
FRc=0
local JRc=U.flat(ERc)
for KRc,LRc in ipairs(ZPc)do
local MRc=(U.flat(LRc.pos)-JRc).Magnitude
if LRc.prog<YQc then
if MRc<=ZQc then
FRc=FRc-2
end
elseif MRc<=jQc then
FRc=FRc+1
end
end
elseif kRc then
FRc=0
local NRc=U.flat(ERc)
for ORc,PRc in ipairs(ZPc)do
if(U.flat(PRc.pos)-NRc).Magnitude<=jQc then
FRc=FRc+PRc.prog*PRc.prog
end
end
elseif lQc and dRc>0 then
local QRc=0
for RRc,SRc in ipairs(cRc)do
local TRc=(U.flat(SRc.pos)-U.flat(ERc)).Magnitude
if TRc<=jQc then
QRc=QRc+SRc.full*SRc.w*(1.1-0.1*TRc/math.max(1,jQc))
end
end
FRc=QRc/dRc*100+bb.cover(ERc,jQc,true)*0.05
else
local URc=bb.cover(ERc,jQc,true,YPc)
if kQc then
URc=bb.cover(ERc,kQc)+URc*0.25
end
FRc=URc+(BRc and 0 or(1-bb.progressAt(ERc))*0.5)
local VRc=0
for WRc,XRc in ipairs(bRc)do
local YRc=XRc.b.types[aRc]
if YRc and(U.flat(XRc.pos)-U.flat(ERc)).Magnitude<=XRc.range then
VRc=math.max(VRc,math.min(YRc,VRc+YRc*XRc.b.uptime))
end
end
FRc=FRc*(1+VRc)
end
if lRc and(U.flat(lRc)-U.flat(ERc)).Magnitude<=mRc then
FRc=FRc+1e6
end
if nRc and(U.flat(nRc)-U.flat(ERc)).Magnitude<=oRc then
FRc=FRc+1e6
end
if pRc then
table.insert(pRc,{p=ERc,sc=FRc})
end
if not yRc or FRc>yRc then
xRc,yRc,zRc=ERc,FRc,bb.cover(ERc,jQc)
end
end
end
if lQc and#cRc>0 and xRc then
local ZRc=false
for _Rc,aSc in ipairs(cRc)do
if(U.flat(aSc.pos)-U.flat(xRc)).Magnitude<=jQc then
ZRc=true
break
end
end
if not ZRc then
return nil,0
end
end
if pRc and#pRc>0 then
table.sort(pRc,function(bSc,cSc)
return bSc.sc>cSc.sc
end)
for dSc=1,math.min(15,#pRc)do
local eSc,fSc=pRc[dSc].p,0
for gSc=0,7 do
local hSc=gSc*math.pi/4
