function bb.lookAt(iSc)
local jSc,kSc=math.huge,nil
for lSc,mSc in ipairs(bb.samples)do
local nSc=(U.flat(mSc.pos)-U.flat(iSc)).Magnitude
if nSc<jSc then
jSc,kSc=nSc,mSc.pos
end
end
local oSc=kSc and U.flat(kSc-iSc)or Vector3 .new(0,0,-1)
return oSc.Magnitude>0.01 and oSc.Unit or Vector3 .new(0,0,-1)
end
function bb.place(pSc,qSc)
local rSc=V.isFarm(pSc.id)
local sSc,tSc=bb.bestSpot(pSc,rSc or V.idol(pSc.id),(bb.trainee~=nil and pSc.uuid==bb.trainee)or V.ENTRY[pSc.id]==true or(bb.studyEntry==true and pSc.id==bb.trialId))
if not sSc then
bb.noSpot[pSc.uuid]=(bb.noSpot[pSc.uuid]or 0)+1
F.status(Sme[4181],Sme[4286]..V.name(pSc.id))
return false
end
local uSc=bb.money()
local vSc=P.caps[pSc.uuid]and bb.count(pSc.uuid)or nil
local wSc,xSc=F.request(Sme[4287],Sme[4288],pSc.uuid,N.Util.CFramePLV(sSc,bb.lookAt(sSc)))
if wSc and xSc then
if vSc and vSc>=(tonumber(P.caps[pSc.uuid])or math.huge)then
F.log(1,Sme[4117],string.format(Sme[4289],V.name(pSc.id),tostring(P.caps[pSc.uuid])))
P.caps[pSc.uuid],P.capsAt[pSc.uuid]=nil,nil
F.saveSoon()
end
bb.spent=bb.spent+(pSc.data.cost or 0)
table.insert(bb.actions,string.format(Sme[4290],V.name(pSc.id)))
F.log(1,Sme[4117],string.format(Sme[4291],V.name(pSc.id),bb.spotKey(sSc),tSc,qSc))
bb.placeLog=bb.placeLog or{}
table.insert(bb.placeLog,{t=math.floor(U.now()-(bb.startT or U.now())),w=bb.wave(),id=pSc.id,x=math.floor(sSc.X),z=math.floor(sSc.Z),cover=math.floor((tSc or 0)+0.5),why=tostring(qSc):sub(1,90)})
F.status(Sme[4181],string.format(Sme[4292],V.name(pSc.id),qSc))
bb.placedAt=bb.placedAt or{}
bb.placedAt[pSc.uuid]=(bb.placedAt[pSc.uuid]or 0)+1
return true
end
if uSc>=(pSc.data.cost or 0)and bb.random then
bb.placeFail=bb.placeFail or{}
bb.placeFail[pSc.uuid]=(bb.placeFail[pSc.uuid]or 0)+1
if bb.placeFail[pSc.uuid]>=2 then
bb.noSpot[pSc.uuid]=3
F.log(1,Sme[4117],string.format(Sme[4293],V.name(pSc.id),bb.fieldCount(),bb.FIELD_MAX))
end
end
if wSc and uSc>=(pSc.data.cost or 0)and not bb.random then
local ySc=bb.spotKey(sSc)
bb.refused[ySc]=true
bb.refusals=(bb.refusals or 0)+1
bb.unitRefusals[pSc.uuid]=(bb.unitRefusals[pSc.uuid]or 0)+1
if not bb.crowded()then
local zSc=bb.mapKey()
P.blocked[zSc]=P.blocked[zSc]or{}
if not bb.refusedRun[ySc]then
P.blocked[zSc][ySc]=(tonumber(P.blocked[zSc][ySc])or 0)+1
bb.refusedRun[ySc]=true
P.blockedAt[zSc]=P.blockedAt[zSc]or{}
P.blockedAt[zSc][ySc]=os.time()
end
if bb.unitRefusals[pSc.uuid]>=3 then
local ASc=math.max(1,bb.count(pSc.uuid))
if P.caps[pSc.uuid]~=ASc or not V.learnedCap(pSc.uuid)then
P.caps[pSc.uuid],P.capsAt[pSc.uuid]=ASc,os.time()
F.log(1,Sme[4117],string.format(Sme[4294],V.name(pSc.id),ASc))
end
end
elseif bb.unitRefusals[pSc.uuid]>=3 and(bb.noSpot[pSc.uuid]or 0)<3 then
bb.noSpot[pSc.uuid]=3
F.log(1,Sme[4117],string.format(Sme[4295],V.name(pSc.id)))
end
if bb.refusals>=bb.REFUSE_FREE then
if not bb.placePause then
F.log(1,Sme[4117],string.format(Sme[4296],bb.refusals,bb.REFUSE_PAUSE))
end
bb.placePause=U.now()+bb.REFUSE_PAUSE
end
F.log(2,Sme[4117],Sme[4297]..ySc..Sme[2947]..V.name(pSc.id))
F.saveSoon()
end
return false
end
