table.insert(bb.trialTrace,string.format(Sme[4298],LSc,KSc-(bb.startT or KSc),MSc,table.concat(OSc,Sme[2884]),QSc,PSc+WSc,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[LSc-1]or 0,bb.teamDps or 0))
end
