P.maps[STc]={v=1,laneV=1,bins=aUc,binsL=cUc and bUc or nil,lanes=cUc,hill=XTc,spots= #WTc,dens=vUc.dens,densN=vUc.densN,binsDensN=vUc.densN or 0,lay=vUc.lay,walk=vUc.walk,walkN=vUc.walkN,sep=cUc and(select(2,pcall(gb.laneSep,bb.samples))or vUc.sep)or nil,hidden=vUc.hidden}
gb._masks={}
