function bb.holdGain(WWc,XWc)
if bb.random or not XWc or not bb.info then
return 0
end
local YWc=V.attackInfo(XWc.atk,XWc.range)
if(YWc.stun or 0)<=0 and(YWc.slowTime or 0)<=0 then
return 0
end
local ZWc=0
for _Wc,aXc in ipairs(bb.mine or{})do
local bXc=aXc._stats
local cXc=V.rows(bXc.id.Value)
local dXc=cXc and cXc[math.min(bXc.upgrade.Value,cXc.max)]
local eXc=dXc and dXc.atk and V.attackInfo(dXc.atk,dXc.range)
if eXc and((eXc.stun or 0)>0 or(eXc.slowTime or 0)>0)then
ZWc=ZWc+1
end
end
local fXc,gXc=gb.mask(bb.info.map,V.range(WWc.u,0)*(bb.info.rangeScale or 1)),0
for hXc=1,gb.BINS do
if fXc[hXc]then
gXc=gXc+1
end
end
local iXc=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
local jXc=(V.airFrom(WWc.id)==0)and 1 or(1-(1-N.FLY_GROUND)*math.min(1,bb.info.flyChance or 0))
return eb.holdGain(YWc,bb.teamDps or 0,gXc/(math.max(0.1,iXc)*gb.BINS)*jXc,ZWc)
end
function bb.buffGain(kXc)
local lXc=V.allyBuff(kXc.id)
if not lXc then
return 0
end
local mXc,nXc,oXc=bb.buffShort(lXc)
local pXc=V.stackCap(lXc.attack)
local qXc,rXc=pcall(V.range,kXc.u,0)
rXc=(qXc and tonumber(rXc)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local sXc=pXc and O.community and tonumber(lXc.time)and tonumber(oXc)
local function tXc(uXc,vXc)
local wXc=math.floor(uXc*lXc.time/math.max(1,oXc)+0.001)
return math.min(pXc,(1+vXc)^wXc-1)
end
local xXc=0
for yXc,zXc in ipairs(mXc)do
local AXc=0
for BXc,CXc in ipairs(mXc)do
if(CXc.pos-zXc.pos).Magnitude<=rXc then
local DXc=lXc.types[CXc.base]
local EXc=DXc*lXc.uptime
if sXc then
local FXc,GXc=tXc(CXc.n,DXc),CXc.n+1
while GXc<CXc.n+6 and tXc(GXc,DXc)<=FXc+0.001 do
GXc=GXc+1
end
EXc=math.max(0,(tXc(GXc,DXc)-FXc)/(GXc-CXc.n))
elseif pXc then
EXc=math.max(0,math.min(pXc,(CXc.n+1)*DXc*lXc.uptime)-math.min(pXc,CXc.n*DXc*lXc.uptime))
end
AXc=AXc+CXc.dps*EXc
end
end
xXc=math.max(xXc,AXc)
end
return xXc*(sXc and 1 or 0.7)
end
function bb.buffWanted(HXc)
return bb.buffGain(HXc)>0.01*(bb.teamDps or 0)
end
bb.summonHist={}
function bb.summonRate()
local IXc,JXc=U.now(),0
for KXc,LXc in pairs(bb.helperDealt)do
JXc=JXc+(tonumber(LXc.v)or 0)
end
local MXc=bb.summonHist
if not MXc[#MXc]or IXc-MXc[#MXc].t>=1 then
table.insert(MXc,{t=IXc,v=JXc})
end
while#MXc>2 and IXc-MXc[1].t>30 do
table.remove(MXc,1)
end
local NXc=MXc[1]
return(NXc and IXc-NXc.t>=5)and math.max(0,JXc-NXc.v)/(IXc-NXc.t)or 0
end
function bb.blessGain(OXc)
if not V.BLESS.by[OXc.id]then
return 0
end
local PXc,QXc=0,0
for RXc,SXc in ipairs(bb.mine or{})do
local TXc=SXc._stats.id.Value
if V.BLESS.by[TXc]then
PXc=PXc+1
end
if V.SUMMONER[TXc]then
QXc=QXc+bb.liveDps(SXc,TXc)
end
end
if PXc>=V.BLESS.cap then
return 0
end
local UXc=math.max(bb.summonRate(),QXc*(1+V.BLESS.dmg*PXc))
return UXc/(1+V.BLESS.dmg*PXc)*V.BLESS.dmg
end
function bb.liveDps(VXc,WXc)
local XXc=VXc:FindFirstChild(Sme[2084])
if not(XXc and XXc:FindFirstChild(Sme[2459])and XXc:FindFirstChild(Sme[2458])and XXc:FindFirstChild(Sme[2273]))then
return 0
end
local YXc=V.SUMMONER[WXc]
local ZXc=math.max(0.1,XXc.attack_cooldown.Value*(YXc and YXc.rate or 1))
local _Xc=(YXc and YXc.atk)or(XXc:FindFirstChild(Sme[2125])and XXc.primary_attack.Value)or nil
local aYc=XXc:FindFirstChild(Sme[2112])and tonumber(XXc.upgrade.Value)or 0
local bYc=0
for cYc,dYc in ipairs({Sme[3913],Sme[4333]})do
local eYc=XXc:FindFirstChild(dYc)
if eYc then
bYc=math.max(bYc,tonumber(eYc.Value)or 0)
end
end
local fYc,gYc=V.types(WXc)
local hYc=Sme[3919]..tostring(gYc)
local iYc=1+(tonumber(VXc:GetAttribute(hYc))or tonumber(XXc:GetAttribute(hYc))or 0)
local jYc=XXc.damage.Value*V.galeDps(WXc,aYc)
return(XXc.damage.Value/ZXc*V.aoe(_Xc,XXc.range.Value)*(1+bYc*0.5)*V.secK(WXc,aYc)+jYc)*V.elem(WXc,bb.mod)*V.nudge(WXc)*iYc*bb.reincMul(VXc)
end
function bb.fullDps(kYc,lYc)
local mYc=bb.liveDps(kYc,lYc)
local nYc=V.rows(lYc)
local oYc=kYc:FindFirstChild(Sme[2084])
local pYc=oYc and oYc:FindFirstChild(Sme[2112])and tonumber(oYc.upgrade.Value)or 0
if not(nYc and nYc.max)or pYc>=nYc.max then
return mYc
end
local function qYc(rYc)
local sYc=nYc[math.min(rYc,nYc.max)]
if not sYc or(tonumber(sYc.cd)or 0)<=0 then
return 0
end
return(tonumber(sYc.damage)or 0)/sYc.cd*V.aoe(sYc.atk,sYc.range)*V.secK(lYc,rYc)
end
local tYc,uYc=qYc(pYc),qYc(nYc.max)
if tYc<=0 or uYc<=0 then
return mYc
end
return mYc*math.max(1,uYc/tYc)
end
function bb.inReach(vYc,wYc)
if not V.SUMMONER[wYc]then
return false
end
local xYc=vYc:FindFirstChild(Sme[2084])
local yYc=xYc and xYc:FindFirstChild(Sme[2273])
if not yYc then
return false
end
local zYc=0
for AYc,BYc in ipairs(bb.mine or{})do
local CYc=BYc:FindFirstChild(Sme[2084])
if CYc and CYc:FindFirstChild(Sme[2398])and V.BLESS.by[CYc.id.Value]then
zYc=zYc+1
