local DYc=yYc.Value*V.reachOf(wYc,zYc)
local EYc=vYc:GetPivot().Position
for FYc,GYc in ipairs(bb.enemies or{})do
local HYc=GYc.pos
if HYc and Vector3 .new(HYc.X-EYc.X,0,HYc.Z-EYc.Z).Magnitude<=DYc then
