local lcd=N.session().override_equipped_units or{}
if lcd[kcd]~=jcd.uuid then
return false
end
if not F.request(Sme[4509],Sme[4510],kcd)then
return false
end
task.wait(0.3)
local mcd=(N.session().override_equipped_units or{})[kcd]~=jcd.uuid
if not mcd and ab.every(Sme[4511],30)then
F.log(1,Sme[4117],Sme[4512]..V.name(jcd.id))
end
return mcd
end
