function bb.summonWorth()
if bb.summonAvg==nil then
local xcd,ycd,zcd=0,0,0
for Acd,Bcd in ipairs(V.equipped())do
local Ccd,Dcd=pcall(V.dps,Bcd.u,0,bb.mod)
xcd,ycd,zcd=xcd+((not V.isFarm(Bcd.id)and Ccd and Dcd)or 0),ycd+1,zcd+(Bcd.data.cost or 0)
end
bb.summonAvg,bb.summonCost=ycd>0 and xcd/ycd or 0,ycd>0 and zcd/ycd or 0
end
local Ecd=bb.bestRate or 0
return Ecd<=0 or bb.summonAvg*2>=Ecd*(10000+bb.summonCost)
end
