qed=sed
end
end
if not qed then
return
end
local ued=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local ved=bb.bestRate or 0
if ued or ved<=0 then
