end
local wed=bb.wave()
local xed=math.max(0,(bb.total or 30)-wed)
local yed=bb.mergePlan
local zed=bb.airLow()
local Aed,Bed,Ced
for Ded,Eed in ipairs(bb.mine)do
local Fed=Eed._stats
local Ged=Fed.id.Value
local Hed=N.Units[Ged]
local Ied=Fed:FindFirstChild(Sme[4119])and tonumber(Fed.total_spent.Value)or 0
if Hed and not Hed.unsellable and Ied>0 and not V.allyBuff(Ged)and not V.idol(Ged)and not(yed and yed.id==Ged)then
local Jed,Ked
if V.isFarm(Ged)then
local Led=Fed:FindFirstChild(Sme[2129])and tonumber(Fed.farm_amount.Value)or 0
local Med=Led*xed
if Ied>Med*1.2 then
Jed=(Ied-Med)*ved
