end
elseif wed>=10 and xed>2 and Ied>=5000 and(bb.upRate[Eed]or 0)<ved/3 and bb.progressAt(Eed:GetPivot().Position)<0.8 and not(zed and bb.canAir(Eed))then
local Ned,Oed=pcall(bb.liveDps,Eed,Ged)
Oed=Ned and Oed or math.huge
if Ied*ved>3*Oed and Oed<0.1*(bb.teamDps or 0)then
Jed=Ied*ved-Oed
Ked=string.format(Sme[4559],U.fmt(Ied))
end
end
if Jed and(not Bed or Jed>Bed)then
Aed,Bed,Ced=Eed,Jed,Ked
end
end
end
if not Aed then
