bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(Red,Sed)
local Ted=(Sed.t or 0)-(Red.t or 0)
if Ted<bb.BASE_WIN-1 then
return false
end
local Ued=((tonumber(Red.base)or 0)-(tonumber(Sed.base)or 0))/Ted
if Ued<=0 or(tonumber(Sed.base)or 0)<=0 then
return false
end
local Ved=Sed.base/Ued
local Wed,Xed=0,0
local Yed,Zed=Red.foes or{},Sed.foes or{}
for _ed,afd in pairs(Zed)do
if afd.prog>=bb.BASE_END then
Wed=Wed+afd.hp
local bfd=Yed[_ed]
if bfd then
Xed=Xed+math.max(0,bfd.hp-afd.hp)
end
end
end
for cfd,dfd in pairs(Yed)do
if dfd.prog>=bb.BASE_END and not Zed[cfd]then
Xed=Xed+dfd.hp
end
end
if Wed<=0 then
return false
end
local efd=Xed/Ted
local ffd=efd>0 and Wed/efd or math.huge
local gfd={baseTime=Ved,loss=Ued,atEnd=Wed,rate=efd,killTime=ffd}
return Ved<bb.BASE_SOON and ffd>Ved*bb.BASE_MARGIN,gfd
end
