function nb.load()
local function LGd(MGd,NGd)
if type(MGd)~=Sme[928]or#MGd==0 then
return nil
end
local OGd,PGd=loadstring(MGd)
if not OGd then
warn(Sme[5132]..NGd..Sme[5133]..tostring(PGd))
return nil
end
local QGd,RGd=pcall(OGd)
if QGd and type(RGd)==Sme[2021]and type(RGd.Window)==Sme[3199]then
return RGd
end
